package sources

import (
	"strings"
	"testing"

	"github.com/veritas501/mem-grep/internal/ir"
)

// These tests cover mem-grep's own rendering of Claude Code's wrapper records, observed in real
// transcripts. They are not a format fixture: a fixture must be generated by Claude Code itself
// (see TODO(fixture) in claude.go).

func TestClaudeUserNote(t *testing.T) {
	model := "<command-name>/model</command-name>\n" +
		"            <command-message>model</command-message>\n" +
		"            <command-args>jd/claude-opus-4.8</command-args>"
	clear := "<command-name>/clear</command-name>\n" +
		"            <command-message>clear</command-message>\n" +
		"            <command-args></command-args>"
	stdout := "<local-command-stdout>Set model to Opus 4 and saved as your default for new sessions</local-command-stdout>"
	tests := []struct {
		text      string
		wantLine  string
		wantStart bool
		wantOK    bool
	}{
		{model, "[user ran /model jd/claude-opus-4.8]", false, true},
		{clear, "[user ran /clear — a new topic likely starts here]", true, true},
		{stdout, "  [command output: Set model to Opus 4 and saved as your default for new sessions]", false, true},
		{"<local-command-stdout>a\n   b</local-command-stdout>", "  [command output: a b]", false, true},
		{"<local-command-stdout></local-command-stdout>", "", false, true},
		{"[Request interrupted by user]", "  [assistant turn aborted by the user]", false, true},
		{"[Request interrupted by user for tool use]", "  [assistant turn aborted by the user]", false, true},
		{"<command-name>/compact</command-name>", "[user ran /compact]", false, true},
		{"<command-name></command-name>", "", false, true},
		{"你好，帮我看下这个报错", "", false, false},
		{"请看 <command-name> 这个写法", "", false, false},
	}
	for _, tt := range tests {
		line, start, ok := claudeUserNote(tt.text)
		if line != tt.wantLine || start != tt.wantStart || ok != tt.wantOK {
			t.Errorf("claudeUserNote(%q) = (%q, %v, %v), want (%q, %v, %v)",
				tt.text, line, start, ok, tt.wantLine, tt.wantStart, tt.wantOK)
		}
	}
}

func TestClaudeWrapperRecordsRenderAsNotes(t *testing.T) {
	buf := []byte(strings.Join([]string{
		`{"type":"user","sessionId":"s1","uuid":"u1","timestamp":"2026-10-30T10:00:00Z","message":{"role":"user","content":"<command-name>/model</command-name>\n<command-message>model</command-message>\n<command-args>jd/claude-opus-4.8</command-args>"}}`,
		`{"type":"user","sessionId":"s1","uuid":"u2","timestamp":"2026-10-30T10:00:01Z","message":{"role":"user","content":"<local-command-stdout>Set model to Opus 4</local-command-stdout>"}}`,
		`{"type":"assistant","sessionId":"s1","uuid":"u3","timestamp":"2026-10-30T10:00:02Z","message":{"role":"assistant","content":[{"type":"text","text":"hi"}]}}`,
		`{"type":"user","sessionId":"s1","uuid":"u4","timestamp":"2026-10-30T10:00:03Z","message":{"role":"user","content":"[Request interrupted by user]"}}`,
	}, "\n") + "\n")
	s, err := (Claude{}).OpenBytes(ir.SourceFile{Path: "s1.jsonl", Size: int64(len(buf))}, buf, ScanOptions{})
	if err != nil || s == nil {
		t.Fatalf("OpenBytes: %v, %v", s, err)
	}
	lines := s.Render(0, -1)
	want := []struct {
		role ir.Role
		text string
	}{
		{ir.RoleNote, "[user ran /model jd/claude-opus-4.8]"},
		{ir.RoleNote, "  [command output: Set model to Opus 4]"},
		{ir.RoleAssistant, "ASSISTANT: hi"},
		{ir.RoleNote, "  [assistant turn aborted by the user]"},
	}
	if len(lines) != len(want) {
		t.Fatalf("got %d lines: %+v", len(lines), lines)
	}
	for i, w := range want {
		if lines[i].Role != w.role || lines[i].Text != w.text {
			t.Errorf("line %d = (%s, %q), want (%s, %q)", i, lines[i].Role, lines[i].Text, w.role, w.text)
		}
	}
	for _, l := range lines {
		if strings.Contains(l.Text, "<command-name>") || strings.HasPrefix(l.Text, "USER: ") {
			t.Errorf("wrapper leaked as user text: %q", l.Text)
		}
	}
}
